package com.citacloud.app.services; import com.citacloud.app.models.*; import com.citacloud.app.repositories.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class DocumentoService {private static final long MAX=10*1024*1024;private static final Set<String> TIPOS=Set.of("application/pdf","image/png","image/jpeg");private final DocumentoRepository repo;private final PacienteRepository pacientes;private final Path raiz;public DocumentoService(DocumentoRepository r,PacienteRepository p,@Value("${app.upload-dir:uploads}") String d){repo=r;pacientes=p;raiz=Paths.get(d).toAbsolutePath().normalize();}public List<Documento> listar(UUID e){return repo.findByEmpresaIdOrderByFechaDesc(e);}@Transactional public Documento subir(UUID e,UUID usuario,UUID pacienteId,String nombre,String descripcion,String archivo,String mime,InputStream datos,long tamano)throws IOException{if(datos==null||tamano<=0||tamano>MAX||!TIPOS.contains(mime))throw new IllegalArgumentException("Solo PDF, PNG o JPG de hasta 10 MB.");Paciente paciente=pacienteId==null?null:pacientes.findByIdAndEmpresaId(pacienteId,e).orElseThrow(()->new IllegalArgumentException("Paciente no encontrado para esta empresa."));String extension=mime.equals("application/pdf")?".pdf":mime.equals("image/png")?".png":".jpg";String seguro=UUID.randomUUID()+extension;Path carpeta=raiz.resolve("documentos").resolve(e.toString()).normalize();Files.createDirectories(carpeta);Path destino=carpeta.resolve(seguro).normalize();if(!destino.startsWith(raiz))throw new IllegalArgumentException("Ruta no válida.");Files.copy(datos,destino,StandardCopyOption.REPLACE_EXISTING);Documento doc=new Documento();doc.setEmpresaId(e);doc.setPaciente(paciente);doc.setUsuarioId(usuario);doc.setNombre(nombre==null||nombre.isBlank()?archivo:nombre.trim());doc.setDescripcion(descripcion);doc.setNombreArchivo(archivo);doc.setRutaArchivo("documentos/"+e+"/"+seguro);doc.setTipo(mime);return repo.save(doc);}public Documento obtener(UUID e,UUID id){return repo.findByIdAndEmpresaId(id,e).orElseThrow(()->new IllegalArgumentException("Documento no encontrado para esta empresa."));}public Path ruta(Documento d){return raiz.resolve(d.getRutaArchivo()).normalize();}}
